class Knoten:
    def __init__(self, wert):
        self.wert = wert
        self.next = None

class VerketteteListe:
    def __init__(self):
        self.head = None

    def vorne_einfuegen(self, wert):
        neu = Knoten(wert)
        neu.next = self.head
        self.head = neu

    def hinten_einfuegen(self, wert):
        neu = Knoten(wert)
        if self.head is None:
            self.head = neu
            return
        akt = self.head
        while akt.next is not None:
            akt = akt.next
        akt.next = neu

    def ausgeben(self):
        akt = self.head
        while akt is not None:
            print(akt.wert, end=" ")
            akt = akt.next
        print()

l = VerketteteListe()
l.hinten_einfuegen(2)
l.hinten_einfuegen(3)
l.vorne_einfuegen(1)
l.ausgeben()    # 1 2 3

# Methode der Klasse VerketteteListe
    def loeschen(self, wert):
        if self.head is None:
            return
        if self.head.wert == wert:
            self.head = self.head.next
            return
        akt = self.head
        while akt.next is not None:
            if akt.next.wert == wert:
                akt.next = akt.next.next
                return
            akt = akt.next

l = VerketteteListe()
for tag in ["Mo", "Di", "Mi", "Do"]:
    l.hinten_einfuegen(tag)
l.loeschen("Mi")
l.loeschen("Mo")
l.ausgeben()    # Di Do
